const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const namibia = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Namibia'));

  const date2019 = ['2019-02-21', '2019-02-28'];
  const baselineDates = ['2003-02-21', '2017-02-28'];

  // 2. Data Acquisition - MODIS NDVI for long-term consistency
  const modis = ee.ImageCollection('MODIS/061/MOD13Q1')
    .select('NDVI')
    .filterBounds(namibia);

  // 2019 data
  const ndvi2019 = modis.filterDate(date2019[0], date2019[1]).first();
  // Baseline data (2003-2017)
  const baseline = modis.filterDate(baselineDates[0], baselineDates[1])
    .filter(ee.Filter.calendarRange(2, 2, 'month')); // Only February

  // Check data availability
  const count2019 = ndvi2019 ? 1 : 0;
  const countBaseline = baseline.size().getInfo();

  console.log(`2019 Images: ${count2019}, Baseline Images: ${countBaseline}`);

  if (count2019 === 0 || countBaseline === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Process 2019 NDVI
  const ndvi2019Mean = ndvi2019.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: namibia,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  // Process baseline NDVI
  const baselineMean = baseline.mean().reduceRegion({
    reducer: ee.Reducer.mean(), 
    geometry: namibia,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  // Check for valid results
  if (ndvi2019Mean === null || baselineMean === null || 
      isNaN(ndvi2019Mean) || isNaN(baselineMean)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Convert MODIS NDVI scale (0.0001)
  const ndvi2019Scaled = ndvi2019Mean * 0.0001;
  const baselineScaled = baselineMean * 0.0001;

  console.log(`2019 NDVI: ${ndvi2019Scaled.toFixed(3)}`);
  console.log(`Baseline NDVI: ${baselineScaled.toFixed(3)}`);
  console.log(`Difference: ${(ndvi2019Scaled - baselineScaled).toFixed(3)}`);

  // Validate NDVI range
  if (ndvi2019Scaled < -1 || ndvi2019Scaled > 1 || 
      baselineScaled < -1 || baselineScaled > 1) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Final comparison - "worse" means lower NDVI
  if (ndvi2019Scaled < baselineScaled) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
